sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {

  // Re-open current route with an ever-changing param to force a fresh instance.
  const route = api.context.route;           // current route name
  const fields = api.context.fields || {};   // keep same fields (if any)
  const currentParams = api.context.props || {};

  helpers.navigate.to(
    route,
    fields,
    {
      ...currentParams,
      // cache-buster to force new page instance
      refresh: Date.now()
    }
  );

}
